{"path": "creative_intent.json", "content": "{
  "user_need": "概念：政治联姻，女主是烈士遗孤，男主是红三代少将。新婚夜发现彼此是十年前在边境战场遇难的青梅竹马（她以为他死了，他以为她瞎了）。现在她是"组织安排的妻子"，他是"必须服从命令的丈夫"，两人都要装作不认识完成政治任务，但旧情在密闭的军区大院新房里复燃。禁区是：承认旧情就是背叛"组织安排"的纯洁性。\n场景：军区大院新房（红色喜庆但压抑，窗外有岗哨，电话可能被监听）\n物件：结婚证（政治文件→旧物→情书，照片NG了十遍才过审）；军装（制服→伪装→裸体下的伤疤）\n疯点：他们必须在哨兵巡逻时安静做爱；他用手势（战场暗语）和她对话，那些手势曾用来杀人现在用来调情；她发现他背上的枪伤是当年为她挡的，但现在他说是"训练中受伤"\n单频振动：压抑的爆发（从伪装→裂缝→共犯→毁灭或重生）\n篇幅：6500-10000字",
  "inspiration_state": "clear_inspiration",
  "extracted_elements": {
    "emotion_verbs": ["装作不认识", "复燃", "压抑", "爆发"],
    "scene_elements": ["军区大院新房", "岗哨监听", "政治联姻", "边境战场回忆"],
    "relationship_tension": ["青梅竹马被迫伪装陌生", "组织安排vs个人情感", "承认旧情=背叛"],
    "user_preferences": {
      "desired_emotion": "压抑的爆发，从伪装到裂缝到共犯到毁灭或重生",
      "forbidden": ["轻易相认", "脱离政治背景的纯爱情", "开放式模糊结局"]
    }
  },
  "selected_recipe": {
    "x_axis_mode_id": "E28",
    "x_axis_mode_name": "爱上仇人",
    "y_axis_tags": ["双向暗恋", "规则怪谈"],
    "reaction_strength": "↘",
    "tension_stars": 5,
    "forbidden_elements": ["承认旧情", "公开相认", "脱离组织控制"],
    "x_axis_display": "恋人属于对立政治阵营（烈士遗孤vs红三代，组织安排的政治婚姻），情感与立场的撕裂",
    "y_axis_combination_effect": "双向暗恋反转为双向伪装（已知却必须装不知）+ 规则怪谈式禁忌（承认=背叛/毁灭），在规则边缘试探的压抑张力",
    "reaction_formula": "对立阵营的旧爱重逢 × 必须伪装的禁忌 × 规则即死亡的压抑 = 情感在高压下的爆发",
    "platform_fit": ["豆瓣阅读", "知乎盐选", "ONE·一个"]
  },
  "one_sentence_synopsis": "新婚夜发现彼此是以为已死的战场青梅竹马，却必须在监听下伪装陌生，旧情在禁忌中复燃。"
}"}

